CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_valida_vista_rol` AS
select `v`.`id_cfg_view` AS `id_cfg_view`,`v`.`name` AS `vista`,`v`.`nmetrics` AS `nmetrics_vista`,`br`.`role_id` AS `role_id`,count(0) AS `n_metricas_rol` from (((`cfg_views` `v` join `cfg_views2metrics` `vm` on((`vm`.`id_cfg_view` = `v`.`id_cfg_view`))) join `sem_metric_binding` `smb` on(((`smb`.`idmetric` = `vm`.`id_metric`) and (`smb`.`status` = 'active')))) join `sem_binding_role` `br` on(((`br`.`instance_id` = `smb`.`instance_id`) and (`br`.`status` = 'active')))) group by `v`.`id_cfg_view`,`v`.`name`,`v`.`nmetrics`,`br`.`role_id`;
